<?php
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/layout.php';require __DIR__.'/includes/appointments.php';
$u=require_user();$error=null;
if(post()) {
 check_csrf();
 try {
  $act=field('act',30);
  if($act==='goal') {
   $goal=filter_var($_POST['weight_kg']??'',FILTER_VALIDATE_FLOAT);
   if($goal===false||$goal<20||$goal>300)throw new RuntimeException('Mục tiêu cân nặng phải từ 20 đến 300 kg.');
   query('INSERT INTO health_goals(user_id,weight_kg) VALUES(?,?) ON DUPLICATE KEY UPDATE weight_kg=VALUES(weight_kg)',[$u['id'],$goal]);
  } elseif($act==='delete_goal') {query('DELETE FROM health_goals WHERE user_id=?',[$u['id']]);}
  elseif($act==='delete_log') {query('DELETE FROM wellness_logs WHERE id=? AND user_id=?',[(int)($_POST['id']??0),$u['id']]);}
  elseif($act==='diary') {
   $date=field('log_date',10);$sleep=filter_var($_POST['sleep_hours']??'',FILTER_VALIDATE_FLOAT);$water=filter_var($_POST['water_ml']??'',FILTER_VALIDATE_INT);$exercise=filter_var($_POST['exercise_minutes']??'',FILTER_VALIDATE_INT);$note=field('note',1000);
   if(!appt_valid_date($date)||$date>date('Y-m-d')||$date<date('Y-m-d',strtotime('-1 year')))throw new RuntimeException('Chọn ngày trong một năm gần đây, không ở tương lai.');
   if($sleep===false||$sleep<0||$sleep>24||$water===false||$water<0||$water>10000||$exercise===false||$exercise<0||$exercise>1440)throw new RuntimeException('Kiểm tra số giờ ngủ (0–24), lượng nước (0–10000 ml) và vận động (0–1440 phút).');
   query('INSERT INTO wellness_logs(user_id,log_date,sleep_hours,water_ml,exercise_minutes,note) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE sleep_hours=VALUES(sleep_hours),water_ml=VALUES(water_ml),exercise_minutes=VALUES(exercise_minutes),note=VALUES(note)',[$u['id'],$date,$sleep,$water,$exercise,$note]);
  } else throw new RuntimeException('Thao tác không hợp lệ.');
  flash('Đã cập nhật sổ sức khỏe của bạn.');redirect('suc-khoe.php');
 } catch(PDOException $ex){error_log((string)$ex);$error='Chưa thể lưu dữ liệu. Vui lòng thử lại.';}catch(RuntimeException $ex){$error=$ex->getMessage();}
}
$logs=query('SELECT * FROM bmi_logs WHERE user_id=? ORDER BY measured_at DESC,id DESC LIMIT 30',[$u['id']])->fetchAll();$latest=$logs[0]??null;
$goal=query('SELECT weight_kg FROM health_goals WHERE user_id=?',[$u['id']])->fetchColumn();
$upcoming=query("SELECT a.*,d.name doctor_name FROM appointments a LEFT JOIN doctors d ON d.id=a.doctor_id WHERE a.user_id=? AND a.status IN ('pending','confirmed') AND TIMESTAMP(a.appt_date,a.appt_time)>NOW() ORDER BY appt_date,appt_time LIMIT 3",[$u['id']])->fetchAll();
$diary=query('SELECT * FROM wellness_logs WHERE user_id=? ORDER BY log_date DESC LIMIT 14',[$u['id']])->fetchAll();
$edit=isset($_GET['edit'])?query('SELECT * FROM wellness_logs WHERE id=? AND user_id=?',[(int)$_GET['edit'],$u['id']])->fetch():null;
$week=query('SELECT COUNT(*) days,ROUND(AVG(sleep_hours),1) sleep,ROUND(AVG(water_ml)) water,SUM(exercise_minutes) exercise FROM wellness_logs WHERE user_id=? AND log_date BETWEEN DATE_SUB(CURDATE(),INTERVAL 6 DAY) AND CURDATE()',[$u['id']])->fetch();
head('Sức khỏe của tôi');notice($error);
?>
<div class="welcome-strip"><div><span class="eyebrow">MỖI NGÀY MỘT CHÚT TỐT HƠN</span><h2>Chào <?php echo e($u['full_name']); ?>.</h2><p>Theo dõi thói quen, lưu các lần đo và chủ động với lịch hẹn của bạn.</p></div><a class="btn btn-brand" href="bmi.php">+ Ghi cân nặng & BMI</a></div>
<div class="metric-grid"><div class="metric-card"><span>BMI gần nhất</span><strong><?php echo e($latest['bmi_value']??'—'); ?></strong><small><?php echo e($latest['classification']??'Chưa có lần đo'); ?></small></div><div class="metric-card"><span>Cân nặng gần nhất</span><strong><?php echo e($latest['weight_kg']??'—'); ?> <small>kg</small></strong><small><?php echo $latest?e(date('d/m/Y',strtotime($latest['measured_at']))):'Ghi lần đo đầu tiên'; ?></small></div><div class="metric-card"><span>Lịch khám sắp tới</span><strong><?php echo count($upcoming); ?></strong><small>Chờ xác nhận / đã xác nhận</small></div><div class="metric-card"><span>Nhật ký 7 ngày gần đây</span><strong><?php echo (int)$week['days']; ?> <small>/ 7 ngày</small></strong><small>Dựa trên ngày bạn đã ghi</small></div></div>
<div class="row g-4 mt-1"><section class="col-lg-8"><div class="hc-panel"><div class="section-heading"><h2 class="h5">Xu hướng cân nặng</h2><a href="bmi.php">Lịch sử BMI →</a></div>
<?php if(count($logs)>1): ?><canvas id="weight-chart" height="260" role="img" aria-label="Biểu đồ cân nặng 30 lần đo gần nhất. Số liệu chi tiết trong trang lịch sử BMI."></canvas><script type="application/json" id="weight-data"><?php echo json_encode(array_reverse(array_map(fn($l)=>['value'=>(float)$l['weight_kg'],'date'=>substr($l['measured_at'],0,10)],$logs)),JSON_HEX_TAG|JSON_HEX_AMP); ?></script><?php else: ?><div class="empty-state">Ghi ít nhất hai lần đo để xem xu hướng cân nặng.</div><?php endif; ?>
<p class="small text-muted mt-3">Các chỉ số giúp ghi nhận thay đổi, không dùng để tự chẩn đoán. Mục tiêu cân nặng do bạn tự nhập; hãy trao đổi với chuyên gia khi cần.</p></div>
<div class="hc-panel mt-4"><h2 class="h5">Nhật ký thói quen</h2><p class="text-muted">Ghi lại một ngày. Lưu lại cùng ngày sẽ cập nhật bản ghi đó.</p><form method="post"><?php echo csrf(); ?><input type="hidden" name="act" value="diary"><div class="row"><div class="col-sm-6"><?php input('log_date','Ngày ghi',$_POST['log_date']??$edit['log_date']??date('Y-m-d'),'date',true); ?></div><div class="col-sm-6"><label for="sleep_hours" class="form-label">Giấc ngủ (giờ)</label><input class="form-control" id="sleep_hours" name="sleep_hours" type="number" step="0.1" min="0" max="24" required value="<?php echo e($_POST['sleep_hours']??$edit['sleep_hours']??''); ?>"></div><div class="col-sm-6"><label for="water_ml" class="form-label">Nước đã uống (ml)</label><input class="form-control" id="water_ml" name="water_ml" type="number" min="0" max="10000" required value="<?php echo e($_POST['water_ml']??$edit['water_ml']??''); ?>"></div><div class="col-sm-6"><label for="exercise_minutes" class="form-label">Vận động (phút)</label><input class="form-control" id="exercise_minutes" name="exercise_minutes" type="number" min="0" max="1440" required value="<?php echo e($_POST['exercise_minutes']??$edit['exercise_minutes']??''); ?>"></div></div><label for="note" class="form-label">Ghi chú</label><textarea id="note" name="note" maxlength="1000" class="form-control" rows="2"><?php echo e($_POST['note']??$edit['note']??''); ?></textarea><button class="btn btn-brand">Lưu nhật ký</button></form>
<div class="table-responsive mt-4"><table class="table align-middle"><caption>14 ngày ghi gần nhất</caption><thead><tr><th>Ngày</th><th>Ngủ</th><th>Nước</th><th>Vận động</th><th>Ghi chú</th><th>Thao tác</th></tr></thead><tbody><?php foreach($diary as $l): ?><tr><td><?php echo e($l['log_date']); ?></td><td><?php echo e($l['sleep_hours']); ?> h</td><td><?php echo (int)$l['water_ml']; ?> ml</td><td><?php echo (int)$l['exercise_minutes']; ?> phút</td><td><?php echo e($l['note']); ?></td><td><a href="?edit=<?php echo (int)$l['id']; ?>#log_date">Sửa</a><form method="post" onsubmit="return confirm('Xóa ngày ghi này?')"><?php echo csrf(); ?><input type="hidden" name="act" value="delete_log"><input type="hidden" name="id" value="<?php echo (int)$l['id']; ?>"><button class="btn btn-sm text-danger">Xóa</button></form></td></tr><?php endforeach; ?><?php if(!$diary): ?><tr><td colspan="6">Bạn chưa ghi nhật ký.</td></tr><?php endif; ?></tbody></table></div></div></section>
<aside class="col-lg-4"><div class="hc-panel"><h2 class="h5">Mục tiêu cá nhân</h2><p><?php echo $goal?'Mục tiêu hiện tại: '.e($goal).' kg':'Bạn chưa đặt mục tiêu cân nặng.'; ?></p><?php if($goal&&$latest): ?><p>Chênh lệch với mục tiêu: <strong><?php echo number_format(abs((float)$latest['weight_kg']-(float)$goal),1); ?> kg</strong></p><?php endif; ?><form method="post"><?php echo csrf(); ?><input type="hidden" name="act" value="goal"><label for="weight_kg" class="form-label">Cân nặng mục tiêu (kg)</label><input class="form-control" id="weight_kg" name="weight_kg" type="number" min="20" max="300" step="0.1" required value="<?php echo e($goal?:''); ?>"><button class="btn btn-outline-brand">Lưu mục tiêu</button></form><?php if($goal): ?><form class="mt-2" method="post"><?php echo csrf(); ?><input type="hidden" name="act" value="delete_goal"><button class="btn btn-sm text-muted">Bỏ mục tiêu</button></form><?php endif; ?></div>
<div class="hc-panel mt-4"><h2 class="h5">7 ngày gần đây</h2><p>Trung bình giấc ngủ: <strong><?php echo e($week['sleep']??'—'); ?> giờ</strong></p><p>Trung bình lượng nước: <strong><?php echo e($week['water']??'—'); ?> ml</strong></p><p>Tổng vận động: <strong><?php echo e($week['exercise']??'—'); ?> phút</strong></p><small>Chỉ tính các ngày đã ghi; đây là thống kê, không phải mức khuyến nghị.</small></div>
<div class="hc-panel mt-4"><h2 class="h5">Lịch hẹn tiếp theo</h2><?php foreach($upcoming as $a): ?><a class="upcoming-link" href="phieu-hen.php?id=<?php echo (int)$a['id']; ?>"><strong><?php echo e(date('d/m',strtotime($a['appt_date'])).' · '.substr($a['appt_time'],0,5)); ?></strong><span><?php echo e($a['doctor_name']??$a['specialty']); ?></span><?php echo appt_badge($a['status']); ?></a><?php endforeach; ?><?php if(!$upcoming): ?><p>Chưa có lịch hẹn sắp tới.</p><?php endif; ?><a class="btn btn-brand w-100 mt-3" href="bac-si.php">Tìm bác sĩ & đặt lịch</a></div>
<div class="hc-panel mt-4"><h2 class="h5">Dữ liệu của bạn</h2><p>Tải lịch sử để tự lưu hoặc trao đổi khi cần.</p><a href="xuat-du-lieu.php?type=bmi">Tải lịch sử BMI (CSV)</a><br><a href="xuat-du-lieu.php?type=diary">Tải nhật ký thói quen (CSV)</a></div></aside></div><script src="assets/js/health-chart.js" defer></script><?php foot(); ?>
